import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addToCart } from '../features/cartSlice';
import { addToWishlist } from '../features/wishlistSlice';
import { FaHeart } from 'react-icons/fa';

function BookCard({ book }) {
  const dispatch = useDispatch();
  const wishlistItems = useSelector(state => state.wishlist.items);
  const isWishlisted = wishlistItems.some(item => item.key === book.key);

  const handleAddToCart = () => {
    dispatch(addToCart(book));
  };

  const handleAddToWishlist = () => {
    dispatch(addToWishlist(book));
  };

  return (
    <div className="book-card">
      {book.coverUrl && (
        <img src={book.coverUrl} alt={book.title} className="book-image" />
      )}
      <h3>{book.title}</h3>
      <p><strong>Author:</strong> {book.author}</p>
      <p><strong>Published:</strong> {book.publishYear}</p>
      <button onClick={handleAddToCart}>Add to Cart</button>
      <button onClick={handleAddToWishlist} disabled={isWishlisted}>
        <FaHeart style={{ color: isWishlisted ? 'red' : 'gray' }} /> Wishlist
      </button>
    </div>
  );
}

export default BookCard;
